using var cts = new CancellationTokenSource();
cts.Cancel();
try
{
    await Task.Delay(1000, cts.Token);
}
catch (OperationCanceledException ex)
{
    Console.WriteLine(ex.GetType().Name);
}

int a = 0, b = 0;
using var cts1 = new CancellationTokenSource();
for (int i = 0; i < 5; i++)
{
    if (i == 2) cts1.Cancel();
    a++;
}
using var cts2 = new CancellationTokenSource();
try
{
    for (int i = 0; i < 5; i++)
    {
        if (i == 2) cts2.Cancel();
        cts2.Token.ThrowIfCancellationRequested();
        b++;
    }
}
catch (OperationCanceledException) { }
Console.WriteLine($"{a} {b}");

using System.Threading.Channels;
var ch = Channel.CreateBounded<int>(new BoundedChannelOptions(2) { FullMode = BoundedChannelFullMode.Wait });
Console.WriteLine(ch.Writer.TryWrite(1));
Console.WriteLine(ch.Writer.TryWrite(2));
Console.WriteLine(ch.Writer.TryWrite(3));
Console.WriteLine(ch.Reader.Count);

using System.Threading.Channels;
var ch = Channel.CreateBounded<int>(new BoundedChannelOptions(3) { FullMode = BoundedChannelFullMode.DropNewest });
for (var i = 1; i <= 5; i++) ch.Writer.TryWrite(i);
ch.Writer.Complete();
var items = new List<int>();
await foreach (var x in ch.Reader.ReadAllAsync()) items.Add(x);
Console.WriteLine(string.Join(",", items));

using System.Threading.Channels;
var ch = Channel.CreateUnbounded<int>();
ch.Writer.TryWrite(1);
ch.Writer.TryWrite(2);
ch.Writer.Complete();
